-- LA FAVORITA V23. EJECUTAR DESPUÉS DE V22.
-- No usar si ya se alteraron los productos manualmente sin respaldo.
-- Mantiene IDs internos, historial y códigos de facturador en external_catalog_links.
BEGIN;
ALTER TABLE products ADD COLUMN IF NOT EXISTS is_service BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE products ADD COLUMN IF NOT EXISTS origin_type TEXT NOT NULL DEFAULT 'SIN DETERMINAR';
CREATE TEMP TABLE lf_v23_codigos(legacy_sku TEXT PRIMARY KEY,sku_nuevo TEXT UNIQUE,nombre TEXT,marca TEXT,categoria TEXT,servicio BOOLEAN,stock_propuesto INTEGER,procedencia TEXT) ON COMMIT DROP;
-- Se actualizan SOLO registros que mantienen su código importado original.
-- El ID (xls-*) no se modifica y el enlace con el facturador permanece.
UPDATE products p SET sku=m.sku_nuevo,name=m.nombre,brand=m.marca,category_id=m.categoria,is_service=m.servicio,origin_type=m.procedencia
FROM lf_v23_codigos m WHERE p.sku=m.legacy_sku;
-- Segunda pasada para bases que ya recibieron los SKU V23; evita reescribir nombres editados.
-- Se incrementan existencias estimadas solo cuando estaban pendientes sin publicar.
UPDATE offers o SET stock=m.stock_propuesto
FROM products p JOIN lf_v23_codigos m ON p.sku=m.sku_nuevo
WHERE o.product_id=p.id AND o.branch_id='sucursal-1' AND o.stock=0 AND o.active=FALSE AND m.servicio=FALSE;
-- Los servicios no consumen inventario.
UPDATE offers o SET stock=0,min_stock=0 FROM products p
WHERE o.product_id=p.id AND p.is_service=TRUE AND o.active=FALSE;
COMMIT;
-- Verificaciones esperadas: 1,292 productos (si se importaron los 1,284 del V22), 14 servicios,
-- stock por sucursal sin compartir y precios del facturador solo en sucursal-1.
SELECT category_id,count(*) FROM products GROUP BY category_id ORDER BY category_id;
SELECT b.id,count(*) FILTER (WHERE o.price>0) precios_con_valor,count(*) FILTER (WHERE o.active) publicados,
SUM(o.stock) unidades_registradas FROM branches b LEFT JOIN offers o ON o.branch_id=b.id GROUP BY b.id ORDER BY b.id;
